SELECT 'gongkao', '年均增长', 'kp-xingce-data-growth-cagr', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "年均增长"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "对多年数据的总变化幅度进行平摊的绝对量和相对量指标。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目中明确出现“年均增加多少”或“年均增长百分之多少”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 年均增长量：", "marks": [{"type": "bold"}]}]}, {"type": "katexBlock", "attrs": {"content": "年均增长量 = \\frac{末期量 - 初期量}{n}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 年均增长率：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 考场上不建议直接开方，建议用代入法验证或使用近似公式。"}]}, {"type": "katexBlock", "attrs": {"content": "(1+r)^n = \\frac{末期量}{初期量} \\quad \\text{或} \\quad r \\approx \\frac{\\frac{末期量}{初期量} - 1}{n}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤（判定 n）"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到年均增长] --> B[最关键:确定年份差 n]\nB --> C{是否为五年规划?}\nC -- 是(如'十三五'期间) --> D[末期年为2020, 初期必须往前推一年取2015! n=5]\nC -- 否(如2018-2023) --> E[直接相减: 2023-2018=5. n=5]\nE --> F[套入公式计算]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2018年产值 1000 亿，2023年为 1500 亿。求这期间的年均增长量？选项：A. 80 B. 100 C. 120 D. 150"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求年均增长量。初期2018，末期2023。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算 n：非五年规划限定，直接减。n = 2023 - 2018 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套公式：(1500 - 1000) / 5 = 500 / 5 = 100。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "初期量年份取错（死亡陷阱）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "求“2018-2023年均”时，有考生觉得包含18,19,20,21,22,23一共6年，除以6。大错特错！年均看的是“跨越的间隔”，就像数线段一样，6个点中间只有5段！永远用减法求 n。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "做题时遇到“十三五期间”、“某某规划期间”，拿红笔把开局年份减去 1 圈出来，强制养成找前一年作为基期的习惯。"}]}]}$$ AS jsonb), NULL, '年均增长的核心考点与实战推导。', category_node.id, CAST('["资料分析", "年均增长"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_cagr", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
